package com.kgsat.order.controller; import com.kgsat.order.model.*; import com.kgsat.order.service.OrderService; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.time.Instant; import static org.mockito.Mockito.*; class OrderControllerTest { @Test void acceptsOrder(){var service=mock(OrderService.class);when(service.create(any())).thenReturn(new OrderEvent("o","c",BigDecimal.ONE,false,Instant.now()));var response=new OrderController(service).create(new OrderRequest("c",BigDecimal.ONE,false));Assertions.assertEquals(202,response.getStatusCode().value());} }
